import{_ as i,o as s,c as e,a2 as t}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"درس التصنيع","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/manufacturing.md","filePath":"ar/guide/tutorials/manufacturing.md"}'),n={name:"ar/guide/tutorials/manufacturing.md"};function l(r,a,o,h,p,d){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="درس-التصنيع" tabindex="-1">درس التصنيع <a class="header-anchor" href="#درس-التصنيع" aria-label="Permalink to &quot;درس التصنيع&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: كيف تُصنع قطعة في مصنع خيالي، من المادة الخام حتى التغليف. ستستخدم الحزمة <code>manufacturing</code> وثيمها <code>industrial</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> part-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manufacturing</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> part-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>safety-mistake</code> و<code>downtime-causes</code>. يعرض <a href="./../../reference/packs.html#manufacturing">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit part-journey</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> المشغّلون والفنيون والمشترون والمتقدمون للعمل. كن دقيقاً، واجعل السلامة أولويتك.</p><ul><li>اعرض المراحل بمكوّن <code>flow</code> مع مؤشر متحرك (token)، مرحلة لكل خطوة منطوقة.</li><li>ميّز فحوص الجودة بـ <code>node</code> يتحول <code>status</code> الخاص به إلى الأخضر عند نطق الكلمة.</li><li>أبقِ المصطلحات التقنية الإنجليزية داخل الجملة العربية.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>خطوات السلامة من الإجراءات الرسمية للعميل فقط.</li><li>المؤشرات (نسبة الهدر، التوقف) من العميل فقط، وإلا فهي «مثال».</li><li>لا معايير تشغيل سرية ولا أسماء شركات أو آلات حقيقية.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> part-journey</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> part-journey</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> part-journey</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/manufacturing/examples/bracket-line-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
